const sourceLines = `-- name: SourceLines :many
SELECT l.id AS line_id, l.receipt_id, l.raw_text, l.line_total_cents,
       CAST(COALESCE(s.name, 'Unassigned') AS TEXT) AS shop_name, r.purchased_at, r.created_at
FROM receipt_lines l
JOIN receipts r ON r.id = l.receipt_id
LEFT JOIN shops s ON s.id = r.shop_id
WHERE l.product_id = ? AND l.kind = 'item'
ORDER BY COALESCE(r.purchased_at, r.created_at) DESC, l.id DESC
LIMIT ?
`

type SourceLinesParams struct {
	ProductID sql.NullInt64 `json:"product_id"`
	Limit     int64         `json:"limit"`
}

type SourceLinesRow struct {
	LineID         int64          `json:"line_id"`
	ReceiptID      int64          `json:"receipt_id"`
	RawText        string         `json:"raw_text"`
	LineTotalCents int64          `json:"line_total_cents"`
	ShopName       string         `json:"shop_name"`
	PurchasedAt    sql.NullString `json:"purchased_at"`
	CreatedAt      string         `json:"created_at"`
}

func (q *Queries) SourceLines(ctx context.Context, arg SourceLinesParams) ([]SourceLinesRow, error) {
	rows, err := q.db.QueryContext(ctx, sourceLines, arg.ProductID, arg.Limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SourceLinesRow{}
	for rows.Next() {
		var i SourceLinesRow
		if err := rows.Scan(
			&i.LineID,
			&i.ReceiptID,
			&i.RawText,
			&i.LineTotalCents,
			&i.ShopName,
			&i.PurchasedAt,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
